// adapters.cpp: a stack of plates, a queue at the counter, and triage.
#include <iostream>
#include <queue>
#include <stack>
#include <string>

int main() {
    std::stack<std::string> plates;
    plates.push("red");
    plates.push("green");
    plates.push("blue");
    std::cout << "top plate: " << plates.top() << '\n';
    plates.pop();
    std::cout << "now on top: " << plates.top() << '\n';

    std::queue<std::string> line;
    line.push("Ana");
    line.push("Ben");
    line.push("Cy");
    std::cout << "served first: " << line.front() << '\n';
    line.pop();
    std::cout << "next up: " << line.front();
    std::cout << ", waiting: " << line.size() << '\n';

    std::priority_queue<int> triage;
    for (int urgency : {3, 9, 1, 7}) triage.push(urgency);
    std::cout << "seen in order:";
    while (!triage.empty()) {
        std::cout << ' ' << triage.top();
        triage.pop();
    }
    std::cout << '\n';
}

