// algos.cpp: five tools from the algorithm toolbox.
#include <algorithm>
#include <iostream>
#include <iterator>
#include <vector>

int main() {
    std::vector<int> temps{18, 25, 31, 22, 29, 15};

    auto hot{std::count_if(temps.begin(), temps.end(),
                           [](int t) { return t > 24; })};
    auto where{std::find(temps.begin(), temps.end(), 22)};
    std::cout << "hot days: " << hot << '\n';
    std::cout << "22 is at index " << where - temps.begin() << '\n';

    std::vector<int> fahr(temps.size());   // 6 boxes, ready to write
    std::transform(temps.begin(), temps.end(), fahr.begin(),
                   [](int c) { return c * 9 / 5 + 32; });

    std::vector<int> warm;                 // empty: back_inserter pushes
    std::copy_if(temps.begin(), temps.end(), std::back_inserter(warm),
                 [](int t) { return t >= 20; });

    std::sort(temps.begin(), temps.end());

    for (int f : fahr) std::cout << f << ' ';
    std::cout << '\n';
    for (int w : warm) std::cout << w << ' ';
    std::cout << '\n';
    for (int t : temps) std::cout << t << ' ';
    std::cout << '\n';
}

