// bfs.cpp: the shortest way out, one ring of squares at a time.
#include <array>
#include <iostream>
#include <queue>
#include <string>
#include <vector>

struct Cell {
    int r;
    int c;
};

int main() {
    std::vector<std::string> grid{"S..#",
                                  ".#..",
                                  "...E"};
    int rows{static_cast<int>(grid.size())};
    int cols{static_cast<int>(grid[0].size())};
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));
    std::array<Cell, 4> moves{{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}};

    std::queue<Cell> todo;
    todo.push({0, 0});
    dist[0][0] = 0;
    while (!todo.empty()) {
        Cell here{todo.front()};
        todo.pop();
        for (Cell m : moves) {
            int r{here.r + m.r};
            int c{here.c + m.c};
            if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
            if (grid[r][c] == '#' || dist[r][c] != -1) continue;
            dist[r][c] = dist[here.r][here.c] + 1;
            todo.push({r, c});
        }
    }
    std::cout << "steps to E: " << dist[2][3] << '\n';
    for (const auto& row : dist) {
        for (int d : row) {
            if (d < 0) std::cout << " #";
            else std::cout << ' ' << d;
        }
        std::cout << '\n';
    }
}

