// boss_trace.cpp: hot potato. Every third pass, the holder is out.
#include <iostream>
#include <queue>

int main() {
    std::queue<char> kids;
    for (char k : {'A', 'B', 'C', 'D'}) kids.push(k);
    for (int pass{1}; kids.size() > 1; ++pass) {
        char holder{kids.front()};
