// capacity.cpp: when does a vector move house?
#include <iostream>
#include <vector>

int main() {
    std::vector<int> v;
    auto room{v.capacity()};
    std::cout << "size 0, capacity 0\n";
    for (int i{1}; i <= 9; ++i) {
        v.push_back(i);
        if (v.capacity() != room) {
            room = v.capacity();
            std::cout << "size " << v.size() << ", capacity " << room << '\n';
        }
    }

    std::vector<int> w;
    w.reserve(9);                        // book 9 rooms up front
    auto before{w.data()};
    for (int i{1}; i <= 9; ++i) w.push_back(i);
    std::cout << "reserved: capacity " << w.capacity()
              << ", moved? " << (w.data() != before ? "yes" : "no") << '\n';
}

