// categories.cpp: three bookmarks with different powers.
#include <forward_list>
#include <iostream>
#include <iterator>
#include <list>
#include <vector>

int main() {
    std::vector<char> v{'a', 'b', 'c', 'd', 'e'};
    std::list<char> l{'a', 'b', 'c', 'd', 'e'};
    std::forward_list<char> f{'a', 'b', 'c', 'd', 'e'};

    auto vi{v.begin() + 3};            // jump there: random access
    auto li{std::next(l.begin(), 3)};  // walk 3 steps: bidirectional
    auto fi{std::next(f.begin(), 3)};  // walk 3 steps: forward only
    std::cout << *vi << ' ' << *li << ' ' << *fi << '\n';

    --vi;                              // a vector bookmark steps back
    --li;                              // so does a list bookmark
    std::cout << *vi << ' ' << *li << '\n';
    std::cout << "vector gap: " << v.end() - vi << '\n';
    std::cout << "list steps: " << std::distance(li, l.end()) << '\n';
}

