// erase_fixed.cpp: two safe ways to throw out the odd numbers.
#include <iostream>
#include <vector>

int main() {
    std::vector<int> a{1, 2, 3, 4, 5, 6};
    for (auto it{a.begin()}; it != a.end();) {
        if (*it % 2 != 0) {
            it = a.erase(it);  // erase hands back the next one
        } else {
            ++it;              // step on only if nothing went
        }
    }
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';

    std::vector<int> b{1, 2, 3, 4, 5, 6};
    auto gone{std::erase_if(b, [](int x) { return x % 2 != 0; })};
    for (int x : b) std::cout << x << ' ';
    std::cout << "(erased " << gone << ")\n";
}

