// family.cpp: a deque, a list and a forward_list doing what they do best.
#include <deque>
#include <forward_list>
#include <iostream>
#include <iterator>
#include <list>
#include <string>

int main() {
    std::deque<int> d{2, 3};
    d.push_front(1);                     // cheap at the front...
    d.push_back(4);                      // ...and at the back
    std::cout << "deque:";
    for (int x : d) std::cout << ' ' << x;

    std::list<std::string> l{"ant", "cat"};
    auto at{std::next(l.begin())};       // a bookmark on "cat"
    l.insert(at, "bee");                 // slip a new bead in before it
    std::cout << "\nlist:";
    for (const auto& s : l) std::cout << ' ' << s;
    std::cout << "\nbookmark still on: " << *at;

    std::forward_list<int> f{10, 30};
    f.insert_after(f.begin(), 20);       // one-way: insert AFTER
    f.push_front(0);
    std::cout << "\nforward_list:";
    for (int x : f) std::cout << ' ' << x;
    std::cout << '\n';
}

