// ranges_proj.cpp: whole containers, and "compare by this part".
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Racer {
    std::string name;
    int seconds;
};

int main() {
    std::vector<int> v{5, 1, 4};
    std::ranges::sort(v);                    // no begin(), no end()
    std::cout << v[0] << ' ' << v[1] << ' ' << v[2] << '\n';

    std::vector<Racer> racers{{"Ada", 52}, {"Bo", 47}, {"Cy", 61}};
    std::ranges::sort(racers, {}, &Racer::seconds);  // by seconds
    for (const auto& r : racers)
        std::cout << r.name << ' ' << r.seconds << '\n';

    auto slow{std::ranges::max_element(racers, {}, &Racer::seconds)};
    auto bo{std::ranges::find(racers, "Bo", &Racer::name)};
    std::cout << "slowest: " << slow->name << '\n';
    std::cout << "Bo took " << bo->seconds << '\n';
}

