    std::cout << "\nkept: " << new_end - v.begin() << '\n';
    v.erase(new_end, v.end());
    std::cout << "after erase, size: " << v.size() << '\n';
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';
}

