// trace_bfs.cpp: which square leaves the queue next?
#include <array>
#include <iostream>
#include <queue>
#include <string>
#include <vector>

struct Cell {
    int r;
    int c;
};

int main() {
    std::vector<std::string> grid{"...",
                                  ".#."};
    std::vector<std::vector<int>> dist(2, std::vector<int>(3, -1));
    std::array<Cell, 4> moves{{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}};   // up, down, left, right
    std::queue<Cell> todo;
    todo.push({0, 0});
    dist[0][0] = 0;
    while (!todo.empty()) {
        Cell here{todo.front()};
        todo.pop();
        for (Cell m : moves) {
            int r{here.r + m.r};
            int c{here.c + m.c};
            if (r < 0 || r > 1 || c < 0 || c > 2) continue;
            if (grid[r][c] == '#' || dist[r][c] != -1) continue;
            dist[r][c] = dist[here.r][here.c] + 1;
            todo.push({r, c});
        }
        std::cout << here.r << ' ' << here.c << ' ' << dist[here.r][here.c] << '\n';
    }
}

