// unique_part.cpp: squash neighbours, then split a row in two.
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> rolls{3, 3, 5, 3, 5, 5, 6};
    rolls.erase(std::unique(rolls.begin(), rolls.end()), rolls.end());
    for (int r : rolls) std::cout << r << ' ';
    std::cout << "(neighbours only)\n";

    std::sort(rolls.begin(), rolls.end());
    rolls.erase(std::unique(rolls.begin(), rolls.end()), rolls.end());
    for (int r : rolls) std::cout << r << ' ';
    std::cout << "(sorted first)\n";

    std::vector<int> n{1, 2, 3, 4, 5, 6, 7, 8};
    auto even{[](int x) { return x % 2 == 0; }};
    auto split{std::stable_partition(n.begin(), n.end(), even)};
    std::cout << "evens:";
    for (auto it{n.begin()}; it != split; ++it) std::cout << ' ' << *it;
    std::cout << " | odds:";
    for (auto it{split}; it != n.end(); ++it) std::cout << ' ' << *it;
    std::cout << '\n';
}

