// views_tour.cpp: four stations from <ranges>.
#include <iostream>
#include <ranges>
#include <string>
#include <vector>

int main() {
    for (int n : std::views::iota(1, 6)) std::cout << n << ' ';
    std::cout << "<- iota(1, 6)\n";

    std::vector<std::string> crew{"Wren", "Pip", "Kit", "Scoot"};
    for (const auto& s : crew | std::views::reverse) std::cout << s << ' ';
    std::cout << "<- reverse\n";

    auto length{[](const std::string& s) { return s.size(); }};
    for (auto len : crew | std::views::transform(length))
        std::cout << len << ' ';
    std::cout << "<- transform to sizes\n";

    auto three{[](const std::string& s) { return s.size() == 3; }};
    auto line = crew | std::views::filter(three) | std::views::take(1);
    for (const auto& s : line) std::cout << s << ' ';
    std::cout << "<- filter, take(1)\n";
    std::cout << "crew still has " << crew.size() << " names\n";
}
